import java.util.*;

public class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        ArrayList<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; ++i) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        // Precompute coprime table for values 1..50
        boolean[][] cop = new boolean[51][51];
        for (int i = 1; i <= 50; ++i) {
            for (int j = 1; j <= 50; ++j) {
                cop[i][j] = gcd(i, j) == 1;
            }
        }

        // For each value, maintain a stack of (node, depth) occurrences along current path
        Deque<int[]>[] stacks = new ArrayDeque[51];
        for (int v = 1; v <= 50; ++v) stacks[v] = new ArrayDeque<>();

        int[] ans = new int[n];
        Arrays.fill(ans, -1);

        // Iterative DFS stack entries: {node, parent, depth, state} state 0 = enter, 1 = exit
        Deque<int[]> dfs = new ArrayDeque<>();
        dfs.addLast(new int[]{0, -1, 0, 0});

        while (!dfs.isEmpty()) {
            int[] cur = dfs.removeLast();
            int node = cur[0], parent = cur[1], depth = cur[2], state = cur[3];
            if (state == 0) {
                // entering node
                int val = nums[node];
                int bestNode = -1;
                int bestDepth = -1;
                // check all possible values that are coprime with val
                for (int v = 1; v <= 50; ++v) {
                    if (!cop[val][v]) continue;
                    if (!stacks[v].isEmpty()) {
                        int[] top = stacks[v].peekLast();
                        int topNode = top[0], topDepth = top[1];
                        if (topDepth > bestDepth) {
                            bestDepth = topDepth;
                            bestNode = topNode;
                        }
                    }
                }
                ans[node] = bestNode == -1 ? -1 : bestNode;

                // push exit marker
                dfs.addLast(new int[]{node, parent, depth, 1});
                // push current node onto its value stack
                stacks[val].addLast(new int[]{node, depth});
                // push children
                for (int nei : graph[node]) {
                    if (nei == parent) continue;
                    dfs.addLast(new int[]{nei, node, depth + 1, 0});
                }
            } else {
                // exiting node: pop from its value stack
                int val = nums[node];
                // It should be non-empty and last must correspond to this node
                if (!stacks[val].isEmpty()) {
                    stacks[val].removeLast();
                }
            }
        }

        return ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

